    headers: { ...(body ? { 'Content-Type': 'application/json' } : {}), ...(token ? { Authorization: `Bearer ${token}` } : {}) },
    ...(body ? { body: JSON.stringify(body) } : {}),
  })
  const payload = await response.json()
  if (!response.ok) throw new AuthError(typeof payload.message === 'string' ? payload.message : 'Authentication request failed.', response.status, payload.errors ?? {})
  return payload
}
