import { AuthError, getMe, logout, type AuthResult } from '../api/auth'
import { AUTH_KEY, AuthContext, type AuthState } from './context'

export default function AuthProvider({ children }: { children: ReactNode }) {
  const [state, setState] = useState<AuthState>({ user: null, loading: true, error: null })
  const [revision, setRevision] = useState(0)
  const token = useRef<string | null>(null)
  const version = useRef(0)
  useEffect(() => {
    const controller = new AbortController()
    const current = ++version.current
    async function restore() {
      try {
        token.current = localStorage.getItem(AUTH_KEY)
        const user = token.current ? await getMe(token.current, controller.signal) : null
        if (!controller.signal.aborted && current === version.current) setState({ user, loading: false, error: null })
      } catch (error) {
        if (controller.signal.aborted || current !== version.current) return
        if (error instanceof AuthError && [401, 403].includes(error.status)) {
          token.current = null
          try { localStorage.removeItem(AUTH_KEY) } catch { /* Storage may be disabled. */ }
          setState({ user: null, loading: false, error: error.status === 403 ? 'This account is blocked.' : null })
        } else setState({ user: null, loading: false, error: 'Unable to verify your account. Please retry.' })
      }
    }
    void restore()
    return () => controller.abort()
  }, [revision])
  useEffect(() => {
    const restore = () => setRevision((value) => value + 1)
    const sync = (event: StorageEvent) => { if (event.key === AUTH_KEY || event.key === null) restore() }
    addEventListener('storage', sync)
    addEventListener('focus', restore)
    return () => { removeEventListener('storage', sync); removeEventListener('focus', restore) }
  }, [])
  const signedIn = useCallback((result: AuthResult) => {
    ++version.current
    // If persistence is blocked, do not claim the session was saved.
    localStorage.setItem(AUTH_KEY, result.token)
    token.current = result.token
    setState({ user: result.data, loading: false, error: null })
  }, [])
  const signOut = useCallback(async () => {
    ++version.current
    const current = token.current
    try { if (current) await logout(current, new AbortController().signal) }
    catch (error) { if (!(error instanceof AuthError) || ![401, 403].includes(error.status)) throw error }
    localStorage.removeItem(AUTH_KEY)
    token.current = null
    setState({ user: null, loading: false, error: null })
  }, [])
  const refresh = useCallback(() => setRevision((value) => value + 1), [])
  const value = useMemo(() => ({ ...state, signedIn, signOut, refresh }), [state, signedIn, signOut, refresh])
  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>
}
